244	static lv_obj_t *launcher_tile(lv_obj_t *parent, uint32_t color,
245	                               const char *glyph, const char *name)
246	{
247	  lv_obj_t *tile = launcher_box(parent, color, LAUNCHER_TILE_RADIUS);
248	
249	  lv_obj_set_style_bg_grad_color(tile,
250	                                 lv_color_darken(lv_color_hex(color),
251	                                                 LV_OPA_30), 0);
252	  lv_obj_set_style_bg_grad_dir(tile, LV_GRAD_DIR_VER, 0);
253	  lv_obj_set_style_transform_width(tile, -8, LV_STATE_PRESSED);
254	  lv_obj_set_style_transform_height(tile, -8, LV_STATE_PRESSED);
255	  lv_obj_set_style_transition(tile, &g_press_trans, 0);
256	
257	  if (glyph != NULL)
258	    {
259	      launcher_label(tile, glyph, &lv_font_montserrat_48, 0xffffff,
260	                     LV_ALIGN_CENTER, 0, -16);
261	    }
262	
263	  if (name != NULL)
264	    {
265	      launcher_label(tile, name, &lv_font_montserrat_24, 0xffffff,
266	                     LV_ALIGN_BOTTOM_LEFT, 24, -20);
267	    }
268	
269	  return tile;
270	}
