281	static lv_obj_t *launcher_app_tile(lv_obj_t *parent, int index,
282	                                   bool named)
283	{
284	  FAR const char *name = builtin_getname(index);
285	  char title[32];
286	  char letter[2];
287	  lv_obj_t *tile;
288	
289	  snprintf(title, sizeof(title), "%c%s", toupper(name[0]), name + 1);
290	  letter[0] = title[0];
291	  letter[1] = '\0';
292	
293	  tile = launcher_tile(parent, g_app_colors[index % nitems(g_app_colors)],
294	                       letter, named ? title : NULL);
295	  launcher_zoom_label(lv_obj_get_child(tile, 0), 50, 50);
296	  return tile;
297	}
