387	                                      0xffffff, LV_ALIGN_TOP_LEFT, 44,
388	                                      2 * LAUNCHER_LIVE_H - 80));
389	  lv_label_set_text_fmt(label, "NuttX + LVGL %d.%d", LVGL_VERSION_MAJOR,
