496	static void launcher_create_home_scr(int last)
497	{
498	  lv_obj_t *scr = launcher_screen();
499	
500	  launcher_label(scr, "openvela", &lv_font_montserrat_48, 0xffffff,
501	                 LV_ALIGN_TOP_LEFT, LAUNCHER_MARGIN, 72);
502	
503	  launcher_label(scr, "LogicPi A1", &lv_font_montserrat_24,
504	                 LAUNCHER_TEXT_DIM, LV_ALIGN_TOP_RIGHT, -LAUNCHER_MARGIN,
505	                 92);
506	
507	  g_home_tiles = lv_obj_create(scr);
508	  lv_obj_remove_style_all(g_home_tiles);
509	  lv_obj_set_scroll_dir(g_home_tiles, LV_DIR_VER);
510	  lv_obj_set_style_pad_bottom(g_home_tiles, LAUNCHER_MARGIN, 0);
511	  lv_obj_set_size(g_home_tiles, LAUNCHER_SCREEN_W - 2 * LAUNCHER_MARGIN,
512	                  LAUNCHER_SCREEN_H - LAUNCHER_TILES_Y);
513	  lv_obj_set_pos(g_home_tiles, LAUNCHER_MARGIN, LAUNCHER_TILES_Y);
514	  launcher_create_tiles(g_home_tiles, last);
515	
