621	  lv_obj_add_event_cb(lock, launcher_drag_event_cb, LV_EVENT_PRESSED, NULL);
622	  lv_obj_add_event_cb(lock, launcher_drag_event_cb, LV_EVENT_PRESSING,
623	                      NULL);
624	  lv_obj_add_event_cb(lock, launcher_drag_event_cb, LV_EVENT_RELEASED,
625	                      NULL);
