99	 * Private Functions
100	 ****************************************************************************/
101	
102	static uint32_t bench_ms(void)
103	{
104	  struct timespec ts;
105	
106	  clock_gettime(CLOCK_MONOTONIC, &ts);
107	  return ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
108	}
109	
110	/****************************************************************************
111	 * Name: CPU and memory tests
112	 ****************************************************************************/
113	
114	static void bench_int(void)
115	{
116	  uint32_t x = g_sink | 1;
117	  int i;
118	
119	  for (i = 0; i < BENCH_INT_LOOPS; i++)
120	    {
121	      x ^= x << 13;
122	      x ^= x >> 17;
123	      x ^= x << 5;
124	    }
125	
126	  g_sink = x;
127	}
128	
129	static void bench_float(void)
130	{
131	  int i;
132	  int j;
133	  int k;
134	
135	  for (i = 0; i < BENCH_MATRIX_N; i++)
136	    {
137	      for (j = 0; j < BENCH_MATRIX_N; j++)
138	        {
139	          float sum = 0.0f;
140	
141	          for (k = 0; k < BENCH_MATRIX_N; k++)
142	            {
143	              sum += g_mat_a[i][k] * g_mat_b[k][j];
144	            }
145	
146	          g_mat_c[i][j] = sum;
147	        }
148	    }
149	
150	  g_sink = (uint32_t)g_mat_c[BENCH_MATRIX_N - 1][BENCH_MATRIX_N - 1];
151	}
152	
153	static void bench_memcpy(void)
154	{
155	  memcpy(g_mem + BENCH_MEM_SIZE, g_mem, BENCH_MEM_SIZE);
156	}
157	
158	static void bench_memset(void)
159	{
160	  memset(g_mem, g_sink, BENCH_MEM_SIZE);
161	}
162	
163	/* Repeat a test for BENCH_TIME_MS, return millions of work units/s */
164	
165	static uint32_t bench_cpu(const struct bench_test_s *t)
166	{
167	  uint32_t start = bench_ms();
168	  uint32_t elapsed;
169	  uint64_t runs = 0;
170	
171	  do
172	    {
173	      t->run();
174	      runs++;
175	      elapsed = bench_ms() - start;
176	    }
177	  while (elapsed < BENCH_TIME_MS);
178	
179	  return runs * t->work / elapsed / 1000;
180	}
