453	/****************************************************************************
454	 * Public Functions
455	 ****************************************************************************/
456	
457	int main(int argc, FAR char *argv[])
458	{
459	  lv_nuttx_dsc_t info;
460	  lv_nuttx_result_t result;
461	  uint32_t idle;
462	  int i;
463	
464	  UNUSED(argc);
465	  UNUSED(argv);
466	
467	  /* LVGL is one global instance, shared by every task of the flat build */
468	
469	  if (lv_is_initialized())
470	    {
471	      fprintf(stderr, "bench: LVGL is busy, start it from the launcher\n");
472	      return 1;
473	    }
474	
475	  g_mem = malloc(2 * BENCH_MEM_SIZE);
476	  if (g_mem == NULL)
477	    {
478	      fprintf(stderr, "bench: memory alloc failed\n");
479	      return 1;
480	    }
481	
482	  for (i = 0; i < BENCH_MATRIX_N * BENCH_MATRIX_N; i++)
483	    {
484	      g_mat_a[i / BENCH_MATRIX_N][i % BENCH_MATRIX_N] = i % 7;
485	      g_mat_b[i / BENCH_MATRIX_N][i % BENCH_MATRIX_N] = i % 5;
486	    }
487	
488	  lv_init();
489	
490	  lv_nuttx_dsc_init(&info);
491	  lv_nuttx_init(&info, &result);
492	
493	  if (result.disp == NULL || result.indev == NULL)
494	    {
495	      fprintf(stderr, "bench: no display or touchscreen\n");
496	      g_running = false;
497	    }
498	  else
499	    {
500	      bench_create();
501	      g_running = true;
502	    }
503	
504	  while (g_running)
505	    {
506	      idle = lv_timer_handler();
507	      usleep(MAX(idle, 1) * 1000);
508	    }
509	
510	  lv_nuttx_deinit(&result);
511	  lv_deinit();
512	  free(g_mem);
513	  return 0;
514	}
