395	/* Layout: live tile, then a 2x2 tile per app, then the small tiles in
396	 * the next free 2x2 block.
397	 */
398	
399	static void launcher_create_tiles(lv_obj_t *parent, int last)
400	{
401	  char list[] = CONFIG_LVX_LAUNCHER_APPS;
402	  FAR char *save;
403	  FAR char *name;
404	  lv_obj_t *tile;
405	  int block = 0;
406	  int index;
407	
408	  launcher_create_live_tile(parent);
409	
410	  for (name = strtok_r(list, " ", &save); name != NULL;
411	       name = strtok_r(NULL, " ", &save))
412	    {
413	      index = builtin_isavail(name);
414	      if (index < 0)
415	        {
416	          continue;
417	        }
418	
419	      tile = launcher_app_tile(parent, index, true);
420	      launcher_place(tile, block % 2 * 2, 2 + block / 2 * 2, 2, 2);
421	      lv_obj_add_event_cb(tile, launcher_app_event_cb, LV_EVENT_CLICKED,
422	                          (void *)(intptr_t)index);
423	      if (index == last)
424	        {
425	          g_return_tile = tile;
426	        }
427	
428	      block++;
429	    }
430	
431	  tile = launcher_tile(parent, LAUNCHER_SYSTEM_COLOR, LV_SYMBOL_SETTINGS,
432	                       "System");
433	  launcher_place(tile, block % 2 * 2, 2 + block / 2 * 2, 1, 1);
434	  lv_obj_add_event_cb(tile, launcher_about_open_cb, LV_EVENT_CLICKED,
435	                      NULL);
436	
437	  tile = launcher_tile(parent, LAUNCHER_SLEEP_COLOR, LV_SYMBOL_POWER,
438	                       "Lock");
439	  launcher_place(tile, block % 2 * 2 + 1, 2 + block / 2 * 2, 1, 1);
440	  lv_obj_add_event_cb(tile, launcher_lock_event_cb, LV_EVENT_CLICKED, NULL);
441	}
