577	static void launcher_drag_event_cb(lv_event_t *e)
578	{
579	  lv_event_code_t code = lv_event_get_code(e);
580	  lv_point_t p;
581	  int32_t dy;
582	
583	  lv_indev_get_point(lv_indev_active(), &p);
584	  dy = MAX(g_drag_start - p.y, 0);
585	
586	  if (code == LV_EVENT_PRESSED)
587	    {
588	      g_drag_start = p.y;
589	    }
590	  else if (code == LV_EVENT_PRESSING)
591	    {
592	      lv_obj_set_style_translate_y(g_lock, -dy, 0);
593	    }
594	  else if (dy > UNLOCK_DRAG_DIST)
595	    {
596	      launcher_unlock();
597	    }
598	  else
599	    {
600	      launcher_anim(g_lock, launcher_translate_y_cb, -dy, 0, 0,
601	                    lv_anim_path_overshoot, NULL);
602	    }
603	}
