27	#define PAINT_SCREEN_W        1080
28	#define PAINT_SCREEN_H        1920
29	#define PAINT_BUF_SIZE        (PAINT_SCREEN_W * PAINT_SCREEN_H * \
30	                               sizeof(uint16_t))
31	
32	#define PAINT_BAR_COLOR       0x1c2b42
33	#define PAINT_BTN_COLOR       0x2a3d5a
34	#define PAINT_BTN_PRESSED     0x3b5378
35	#define PAINT_BTN_SIZE        96
36	#define PAINT_SWATCH_SIZE     64
37	
38	/****************************************************************************
39	 * Private Data
40	 ****************************************************************************/
41	
42	static lv_obj_t *g_canvas;
43	static lv_obj_t *g_swatch;
44	static lv_obj_t *g_size_dot;
45	static uint16_t *g_canvas_buf;
46	static uint16_t g_brush_color;
47	static lv_point_t g_brush_prev;
48	static int g_brush_size;
49	static bool g_running;
50	
51	static const uint32_t g_palette[] =
52	{
53	  0x111111, 0xffffff, 0xe8443a, 0xf5a623, 0x27c24a, 0x00a8f3, 0x8e5cf7
54	};
55	
56	static const int32_t g_brush_radius[] =
57	{
58	  4, 10, 20
59	};
60	
61	/****************************************************************************
62	 * Private Functions
63	 ****************************************************************************/
64	
65	static lv_obj_t *paint_button(lv_obj_t *parent, int32_t size,
66	                              uint32_t color, lv_event_cb_t cb)
67	{
68	  lv_obj_t *btn = lv_obj_create(parent);
69	
70	  lv_obj_remove_style_all(btn);
71	  lv_obj_remove_flag(btn, LV_OBJ_FLAG_SCROLLABLE);
72	  lv_obj_set_size(btn, size, size);
73	  lv_obj_set_style_radius(btn, LV_RADIUS_CIRCLE, 0);
74	  lv_obj_set_style_bg_opa(btn, LV_OPA_COVER, 0);
75	  lv_obj_set_style_bg_color(btn, lv_color_hex(color), 0);
76	  lv_obj_add_event_cb(btn, cb, LV_EVENT_CLICKED, NULL);
77	  return btn;
78	}
79	
80	static void paint_icon_button(lv_obj_t *parent, const char *symbol,
81	                              lv_event_cb_t cb)
82	{
83	  lv_obj_t *btn = paint_button(parent, PAINT_BTN_SIZE, PAINT_BTN_COLOR, cb);
84	  lv_obj_t *label = lv_label_create(btn);
85	
86	  lv_obj_set_style_bg_color(btn, lv_color_hex(PAINT_BTN_PRESSED),
87	                            LV_STATE_PRESSED);
88	  lv_obj_set_style_text_font(label, &lv_font_montserrat_24, 0);
89	  lv_obj_set_style_text_color(label, lv_color_white(), 0);
90	  lv_label_set_text(label, symbol);
91	  lv_obj_center(label);
92	}
93	
94	static void paint_dot(int32_t x, int32_t y)
95	{
96	  int32_t r = g_brush_radius[g_brush_size];
97	  int32_t dx;
98	  int32_t dy;
99	
100	  for (dy = -r; dy <= r; dy++)
101	    {
102	      for (dx = -r; dx <= r; dx++)
103	        {
104	          if (dx * dx + dy * dy <= r * r &&
105	              x + dx >= 0 && x + dx < PAINT_SCREEN_W &&
106	              y + dy >= 0 && y + dy < PAINT_SCREEN_H)
107	            {
108	              g_canvas_buf[(y + dy) * PAINT_SCREEN_W + x + dx] =
109	                g_brush_color;
110	            }
111	        }
112	    }
113	}
114	
115	static void paint_stroke(int32_t x0, int32_t y0, int32_t x1, int32_t y1)
116	{
117	  int32_t r = g_brush_radius[g_brush_size];
118	  int32_t dx = x1 - x0;
119	  int32_t dy = y1 - y0;
120	  int32_t steps = MAX(LV_ABS(dx), LV_ABS(dy));
121	  int32_t i;
122	  lv_area_t area =
123	    {
124	      MIN(x0, x1) - r, MIN(y0, y1) - r, MAX(x0, x1) + r, MAX(y0, y1) + r
125	    };
126	
127	  for (i = 0; i < steps; i += r / 2 + 1)
128	    {
129	      paint_dot(x0 + dx * i / steps, y0 + dy * i / steps);
130	    }
131	
132	  paint_dot(x1, y1);
133	  lv_obj_invalidate_area(g_canvas, &area);
134	}
135	
136	static void paint_canvas_event_cb(lv_event_t *e)
137	{
138	  lv_point_t p;
139	
140	  lv_indev_get_point(lv_indev_active(), &p);
141	
142	  if (lv_event_get_code(e) == LV_EVENT_PRESSED)
143	    {
144	      g_brush_prev = p;
145	    }
146	
147	  paint_stroke(g_brush_prev.x, g_brush_prev.y, p.x, p.y);
148	  g_brush_prev = p;
149	}
150	
151	static void paint_home_cb(lv_event_t *e)
152	{
153	  UNUSED(e);
154	  g_running = false;
155	}
156	
157	static void paint_clear_cb(lv_event_t *e)
158	{
159	  UNUSED(e);
160	  lv_canvas_fill_bg(g_canvas, lv_color_white(), LV_OPA_COVER);
161	}
162	
163	static void paint_size_cb(lv_event_t *e)
164	{
165	  int32_t d;
166	
167	  UNUSED(e);
168	
169	  g_brush_size = (g_brush_size + 1) % nitems(g_brush_radius);
170	  d = 2 * g_brush_radius[g_brush_size];
171	  lv_obj_set_size(g_size_dot, d, d);
172	}
173	
174	static void paint_color_cb(lv_event_t *e)
175	{
176	  lv_obj_t *swatch = lv_event_get_target(e);
177	  lv_color_t c = lv_obj_get_style_bg_color(swatch, 0);
178	
179	  lv_obj_remove_state(g_swatch, LV_STATE_CHECKED);
180	  lv_obj_add_state(swatch, LV_STATE_CHECKED);
181	  lv_obj_set_style_bg_color(g_size_dot, c, 0);
182	  g_brush_color = lv_color_to_u16(c);
183	  g_swatch = swatch;
184	}
185	
186	static void paint_create(void)
187	{
188	  lv_obj_t *scr = lv_screen_active();
189	  lv_obj_t *bar;
190	  lv_obj_t *obj;
191	  int i;
192	
193	  g_canvas = lv_canvas_create(scr);
194	  lv_canvas_set_buffer(g_canvas, g_canvas_buf, PAINT_SCREEN_W,
195	                       PAINT_SCREEN_H, LV_COLOR_FORMAT_RGB565);
196	  lv_canvas_fill_bg(g_canvas, lv_color_white(), LV_OPA_COVER);
197	  lv_obj_add_flag(g_canvas, LV_OBJ_FLAG_CLICKABLE);
198	  lv_obj_add_event_cb(g_canvas, paint_canvas_event_cb, LV_EVENT_PRESSED,
199	                      NULL);
200	  lv_obj_add_event_cb(g_canvas, paint_canvas_event_cb, LV_EVENT_PRESSING,
201	                      NULL);
202	
203	  /* Floating tool bar: home, palette, brush size, clear */
204	
205	  bar = lv_obj_create(scr);
206	  lv_obj_remove_style_all(bar);
207	  lv_obj_remove_flag(bar, LV_OBJ_FLAG_SCROLLABLE);
208	  lv_obj_set_size(bar, PAINT_SCREEN_W - 48, 136);
209	  lv_obj_set_style_radius(bar, LV_RADIUS_CIRCLE, 0);
210	  lv_obj_set_style_bg_opa(bar, LV_OPA_90, 0);
211	  lv_obj_set_style_bg_color(bar, lv_color_hex(PAINT_BAR_COLOR), 0);
212	  lv_obj_set_flex_flow(bar, LV_FLEX_FLOW_ROW);
213	  lv_obj_set_flex_align(bar, LV_FLEX_ALIGN_SPACE_EVENLY,
214	                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
215	  lv_obj_align(bar, LV_ALIGN_TOP_MID, 0, 24);
216	
217	  paint_icon_button(bar, LV_SYMBOL_HOME, paint_home_cb);
218	
219	  for (i = 0; i < nitems(g_palette); i++)
220	    {
221	      obj = paint_button(bar, PAINT_SWATCH_SIZE, g_palette[i],
222	                         paint_color_cb);
223	      lv_obj_set_style_outline_color(obj, lv_color_white(),
224	                                     LV_STATE_CHECKED);
225	      lv_obj_set_style_outline_width(obj, 5, LV_STATE_CHECKED);
226	      lv_obj_set_style_outline_pad(obj, 5, LV_STATE_CHECKED);
227	      if (i == 0)
228	        {
229	          g_swatch = obj;
230	        }
231	    }
232	
233	  obj = paint_button(bar, PAINT_BTN_SIZE, PAINT_BTN_COLOR, paint_size_cb);
234	  lv_obj_set_style_bg_color(obj, lv_color_hex(PAINT_BTN_PRESSED),
235	                            LV_STATE_PRESSED);
236	
237	  g_size_dot = lv_obj_create(obj);
238	  lv_obj_remove_style_all(g_size_dot);
239	  lv_obj_remove_flag(g_size_dot, LV_OBJ_FLAG_CLICKABLE);
240	  lv_obj_set_style_radius(g_size_dot, LV_RADIUS_CIRCLE, 0);
241	  lv_obj_set_style_bg_opa(g_size_dot, LV_OPA_COVER, 0);
242	  lv_obj_set_style_border_color(g_size_dot, lv_color_white(), 0);
243	  lv_obj_set_style_border_width(g_size_dot, 2, 0);
244	  lv_obj_center(g_size_dot);
245	
246	  paint_icon_button(bar, LV_SYMBOL_TRASH, paint_clear_cb);
247	
248	  /* Start with the medium brush and the first color */
249	
250	  g_brush_size = 0;
251	  paint_size_cb(NULL);
252	  lv_obj_send_event(g_swatch, LV_EVENT_CLICKED, NULL);
253	}
