/****************************************************************************
 * app/paint/digit.h
 *
 * Handwritten digit recognition: strokes -> 28x28 MNIST style image ->
 * 784-128-10 MLP.  Plain C, so tools/digit_test.c runs it on the host.
 ****************************************************************************/

#ifndef __APP_PAINT_DIGIT_H
#define __APP_PAINT_DIGIT_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdint.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define DIGIT_SIZE            28
#define DIGIT_INPUTS          (DIGIT_SIZE * DIGIT_SIZE)
#define DIGIT_HIDDEN          128
#define DIGIT_CLASSES         10

/* Point that ends a stroke */

#define DIGIT_PEN_UP          INT16_MIN

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct digit_point_s
{
  int16_t x;
  int16_t y;                /* DIGIT_PEN_UP between strokes */
};

/****************************************************************************
 * Public Data
 ****************************************************************************/

extern const float g_digit_s1;
extern const float g_digit_s2;
extern const int8_t g_digit_w1[DIGIT_HIDDEN * DIGIT_INPUTS];
extern const float g_digit_b1[DIGIT_HIDDEN];
extern const int8_t g_digit_w2[DIGIT_CLASSES * DIGIT_HIDDEN];
extern const float g_digit_b2[DIGIT_CLASSES];

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Render strokes into a 0..1 gray image the way MNIST digits look */

void digit_preprocess(const struct digit_point_s *pts, int npts,
                      float img[DIGIT_INPUTS]);

/* Return the most likely digit, prob gets the softmax output */

int digit_classify(const float img[DIGIT_INPUTS],
                   float prob[DIGIT_CLASSES]);

#endif /* __APP_PAINT_DIGIT_H */

/****************************************************************************
 * app/paint/digit.c
 *
 * Handwritten digit recognition, see digit.h.
 *
 * Screen strokes are 16px wide on a 1080px canvas.  Shrinking the pixels
 * to 28x28 leaves lines far thinner than anything in MNIST, so the stroke
 * points are scaled instead and the lines are drawn again with MNIST
 * width.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <math.h>
#include <string.h>

#include "digit.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* The longer side of the stroke skeleton, plus the pen gives about 20px */

#define DIGIT_BOX             17.6f

/* Pen: solid up to 1.2px from the center, fading out at 1.7px */

#define DIGIT_PEN_SOLID       1.2f
#define DIGIT_PEN_EDGE        1.7f

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Squared distance from (px, py) to the segment (ax, ay) - (bx, by) */

static float digit_dist2(float px, float py, float ax, float ay,
                         float bx, float by)
{
  float dx = bx - ax;
  float dy = by - ay;
  float len2 = dx * dx + dy * dy;
  float t = 0.0f;

  if (len2 > 0.0f)
    {
      t = ((px - ax) * dx + (py - ay) * dy) / len2;
      t = t < 0.0f ? 0.0f : t > 1.0f ? 1.0f : t;
    }

  dx = ax + t * dx - px;
  dy = ay + t * dy - py;
  return dx * dx + dy * dy;
}

/* Draw the strokes mapped by grid = (p - c) * scale + off */

static void digit_render(const struct digit_point_s *pts, int npts,
                         float cx, float cy, float scale, float offx,
                         float offy, float img[DIGIT_INPUTS])
{
  float px;
  float py;
  float d;
  int x;
  int y;
  int i;

  for (y = 0; y < DIGIT_SIZE; y++)
    {
      for (x = 0; x < DIGIT_SIZE; x++)
        {
          px = x + 0.5f;
          py = y + 0.5f;
          d = DIGIT_PEN_EDGE * DIGIT_PEN_EDGE;

          for (i = 0; i < npts; i++)
            {
              const struct digit_point_s *a = &pts[i];
              const struct digit_point_s *b = &pts[i];

              if (a->y == DIGIT_PEN_UP)
                {
                  continue;
                }

              /* Single points draw a dot */

              if (i + 1 < npts && pts[i + 1].y != DIGIT_PEN_UP)
                {
                  b = &pts[i + 1];
                }

              d = fminf(d, digit_dist2(px, py,
                                       (a->x - cx) * scale + offx,
                                       (a->y - cy) * scale + offy,
                                       (b->x - cx) * scale + offx,
                                       (b->y - cy) * scale + offy));
            }

          d = (DIGIT_PEN_EDGE - sqrtf(d)) /
              (DIGIT_PEN_EDGE - DIGIT_PEN_SOLID);
          img[y * DIGIT_SIZE + x] = d < 0.0f ? 0.0f : d > 1.0f ? 1.0f : d;
        }
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void digit_preprocess(const struct digit_point_s *pts, int npts,
                      float img[DIGIT_INPUTS])
{
  int16_t x0 = INT16_MAX;
  int16_t y0 = INT16_MAX;
  int16_t x1 = INT16_MIN;
  int16_t y1 = INT16_MIN;
  float scale = 0.0f;
  float sum = 0.0f;
  float mx = 0.0f;
  float my = 0.0f;
  int i;

  for (i = 0; i < npts; i++)
    {
      if (pts[i].y != DIGIT_PEN_UP)
        {
          x0 = pts[i].x < x0 ? pts[i].x : x0;
          x1 = pts[i].x > x1 ? pts[i].x : x1;
          y0 = pts[i].y < y0 ? pts[i].y : y0;
          y1 = pts[i].y > y1 ? pts[i].y : y1;
        }
    }

  memset(img, 0, DIGIT_INPUTS * sizeof(float));
  if (x0 > x1)
    {
      return;
    }

  if (x1 - x0 > 0 || y1 - y0 > 0)
    {
      scale = DIGIT_BOX / (x1 - x0 > y1 - y0 ? x1 - x0 : y1 - y0);
    }

  /* Draw around the box center, then again with the center of mass moved
   * to the middle of the grid as MNIST does.
   */

  digit_render(pts, npts, (x0 + x1) / 2.0f, (y0 + y1) / 2.0f, scale,
               DIGIT_SIZE / 2.0f, DIGIT_SIZE / 2.0f, img);

  for (i = 0; i < DIGIT_INPUTS; i++)
    {
      sum += img[i];
      mx += img[i] * (i % DIGIT_SIZE + 0.5f);
      my += img[i] * (i / DIGIT_SIZE + 0.5f);
    }

  if (sum > 0.0f)
    {
      digit_render(pts, npts, (x0 + x1) / 2.0f, (y0 + y1) / 2.0f, scale,
                   DIGIT_SIZE - mx / sum, DIGIT_SIZE - my / sum, img);
    }
}

int digit_classify(const float img[DIGIT_INPUTS],
                   float prob[DIGIT_CLASSES])
{
  float hidden[DIGIT_HIDDEN];
  const int8_t *w;
  float sum;
  float max;
  int best = 0;
  int i;
  int j;

  for (i = 0; i < DIGIT_HIDDEN; i++)
    {
      w = &g_digit_w1[i * DIGIT_INPUTS];
      sum = 0.0f;

      for (j = 0; j < DIGIT_INPUTS; j++)
        {
          sum += w[j] * img[j];
        }

      sum = sum * g_digit_s1 + g_digit_b1[i];
      hidden[i] = sum > 0.0f ? sum : 0.0f;
    }

  for (i = 0; i < DIGIT_CLASSES; i++)
    {
      w = &g_digit_w2[i * DIGIT_HIDDEN];
      sum = 0.0f;

      for (j = 0; j < DIGIT_HIDDEN; j++)
        {
          sum += w[j] * hidden[j];
        }

      prob[i] = sum * g_digit_s2 + g_digit_b2[i];
      best = prob[i] > prob[best] ? i : best;
    }

  /* Softmax */

  max = prob[best];
  sum = 0.0f;

  for (i = 0; i < DIGIT_CLASSES; i++)
    {
      prob[i] = expf(prob[i] - max);
      sum += prob[i];
    }

  for (i = 0; i < DIGIT_CLASSES; i++)
    {
      prob[i] /= sum;
    }

  return best;
}

/****************************************************************************
 * app/paint/tools/digit_test.c
 *
 * Host test for digit.c:
 *   1. MNIST test set through digit_classify(), must match train.py
 *   2. Synthetic touch strokes of 0-9 through digit_preprocess(), the way
 *      paint feeds the model on the board
 *
 *   cc -O2 -I.. -o digit_test digit_test.c ../digit.c ../digit_model.c \
 *      -lz -lm
 *   ./digit_test <mnist dir>
 ****************************************************************************/

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

#include "digit.h"

#define SAMPLES     50
#define MAX_POINTS  2048
#define PI          3.14159265f

/* Digits as pen paths in a unit box, strokes end with a -1 point */

struct seg_s
{
  float x;
  float y;
};

static const struct seg_s g_shapes[10][16] =
{
  { {.5, 0}, {.15, .2}, {.08, .55}, {.25, .92}, {.55, 1}, {.85, .8},
    {.92, .4}, {.75, .08}, {.45, .02}, {-1, -1} },
  { {.35, .15}, {.55, 0}, {.55, 1}, {-1, -1} },
  { {.12, .25}, {.35, .02}, {.7, .02}, {.88, .25}, {.75, .5}, {.1, 1},
    {.92, 1}, {-1, -1} },
  { {.12, .1}, {.5, 0}, {.85, .15}, {.8, .4}, {.42, .5}, {.85, .6},
    {.9, .85}, {.5, 1}, {.1, .9}, {-1, -1} },
  { {.6, 0}, {.08, .65}, {.95, .65}, {-1, -1}, {.68, .3}, {.68, 1},
    {-1, -1} },
  { {.85, 0}, {.22, 0}, {.15, .45}, {.55, .38}, {.86, .58}, {.82, .88},
    {.45, 1}, {.1, .9}, {-1, -1} },
  { {.75, 0}, {.35, .3}, {.15, .65}, {.25, .95}, {.6, 1}, {.85, .8},
    {.75, .55}, {.4, .5}, {.18, .65}, {-1, -1} },
  { {.08, 0}, {.92, 0}, {.4, 1}, {-1, -1} },
  { {.75, .12}, {.5, 0}, {.22, .12}, {.25, .35}, {.75, .62}, {.82, .88},
    {.5, 1}, {.18, .88}, {.25, .62}, {.75, .35}, {.75, .12}, {-1, -1} },
  { {.85, .25}, {.55, .45}, {.2, .32}, {.3, .05}, {.7, 0}, {.85, .25},
    {.8, .6}, {.7, 1}, {-1, -1} },
};

static float frand(float lo, float hi)
{
  return lo + (hi - lo) * rand() / (float)RAND_MAX;
}

/* Sample a digit the way the touch panel reports a moving finger:
 * random size, aspect, slant and tremble, a point every 6-20px.
 */

static int synth(int digit, struct digit_point_s *pts)
{
  const struct seg_s *s = g_shapes[digit];
  float h = frand(300, 900);
  float w = h * frand(.5f, .8f);
  float slant = frand(-.25f, .25f);
  float ox = frand(100, 1080 - 100 - w);
  float oy = frand(200, 1700 - h);
  float x;
  float y;
  float len;
  float t;
  float step;
  int n = 0;
  int i;

  for (i = 0; s[i].x >= 0 || s[i + 1].x >= 0; i++)
    {
      if (s[i].x < 0)
        {
          pts[n++].y = DIGIT_PEN_UP;
          continue;
        }

      if (s[i + 1].x < 0)
        {
          continue;
        }

      len = hypotf((s[i + 1].x - s[i].x) * w, (s[i + 1].y - s[i].y) * h);
      for (t = 0; t < len && n < MAX_POINTS - 2; t += step)
        {
          step = frand(6, 20);
          x = s[i].x + (s[i + 1].x - s[i].x) * t / len;
          y = s[i].y + (s[i + 1].y - s[i].y) * t / len;
          pts[n].x = ox + (x + slant * (1 - y)) * w + frand(-4, 4);
          pts[n].y = oy + y * h + frand(-4, 4);
          n++;
        }
    }

  pts[n].x = ox + (s[i - 1].x + slant * (1 - s[i - 1].y)) * w;
  pts[n].y = oy + s[i - 1].y * h;
  n++;
  pts[n++].y = DIGIT_PEN_UP;
  return n;
}

static void show(const float img[DIGIT_INPUTS])
{
  int x;
  int y;

  for (y = 0; y < DIGIT_SIZE; y++)
    {
      for (x = 0; x < DIGIT_SIZE; x++)
        {
          putchar(" .:-=+*#%@"[(int)(img[y * DIGIT_SIZE + x] * 9.99f)]);
        }

      putchar('\n');
    }
}

static unsigned char *load(const char *dir, const char *name, int offset,
                           int size)
{
  unsigned char *buf = malloc(offset + size);
  char path[512];
  gzFile f;

  snprintf(path, sizeof(path), "%s/%s", dir, name);
  f = gzopen(path, "rb");
  if (f == NULL || gzread(f, buf, offset + size) != offset + size)
    {
      fprintf(stderr, "cannot read %s\n", path);
      exit(1);
    }

  gzclose(f);
  return buf;
}

int main(int argc, char *argv[])
{
  static struct digit_point_s pts[MAX_POINTS];
  float img[DIGIT_INPUTS];
  float prob[DIGIT_CLASSES];
  unsigned char *images;
  unsigned char *labels;
  int correct = 0;
  int total = 0;
  int digit;
  int i;
  int j;

  if (argc < 2)
    {
      fprintf(stderr, "usage: %s <mnist dir>\n", argv[0]);
      return 1;
    }

  images = load(argv[1], "t10k-images-idx3-ubyte.gz", 16,
                10000 * DIGIT_INPUTS);
  labels = load(argv[1], "t10k-labels-idx1-ubyte.gz", 8, 10000);

  for (i = 0; i < 10000; i++)
    {
      for (j = 0; j < DIGIT_INPUTS; j++)
        {
          img[j] = images[16 + i * DIGIT_INPUTS + j] / 255.0f;
        }

      correct += digit_classify(img, prob) == labels[8 + i];
    }

  printf("MNIST test set: %.2f%%\n\n", correct / 100.0f);

  srand(349);
  for (digit = 0; digit < 10; digit++)
    {
      correct = 0;
      for (i = 0; i < SAMPLES; i++)
        {
          digit_preprocess(pts, synth(digit, pts), img);
          j = digit_classify(img, prob);
          correct += j == digit;
          if (i == 0)
            {
              printf("digit %d -> %d (%.1f%%)\n", digit, j, prob[j] * 100);
              show(img);
            }
        }

      printf("digit %d: %d/%d\n\n", digit, correct, SAMPLES);
      total += correct;
    }

  printf("synthetic strokes: %d/%d\n", total, 10 * SAMPLES);
  return 0;
}

