339	/* With three or more items the first is a tall tile on the left and the
340	 * next two stack beside it.  The rest go two per row, a last odd one
341	 * takes the whole row.  Returns the number of rows used.
342	 */
343	
344	static int launcher_place_tile(lv_obj_t *tile, int i, int n)
345	{
346	  int32_t step = LAUNCHER_TILE_H + UI_GAP;
347	  int32_t right = UI_MARGIN + LAUNCHER_HALF_W + UI_GAP;
348	  int k = n >= 3 ? i - 3 : i;
349	  int row = (n >= 3 ? 2 : 0) + k / 2;
350	
351	  if (n >= 3 && i == 0)
352	    {
353	      lv_obj_set_pos(tile, UI_MARGIN, LAUNCHER_TILES_Y);
354	      lv_obj_set_size(tile, LAUNCHER_HALF_W, LAUNCHER_TILE_H + step);
355	      return 2;
356	    }
357	
358	  if (n >= 3 && i < 3)
359	    {
360	      lv_obj_set_pos(tile, right, LAUNCHER_TILES_Y + (i - 1) * step);
361	      lv_obj_set_size(tile, LAUNCHER_HALF_W, LAUNCHER_TILE_H);
362	      return 2;
363	    }
364	
365	  lv_obj_set_pos(tile, k % 2 ? right : UI_MARGIN,
366	                 LAUNCHER_TILES_Y + row * step);
367	  lv_obj_set_size(tile, k % 2 == 0 && i == n - 1 ? UI_CONTENT_W :
368	                  LAUNCHER_HALF_W, LAUNCHER_TILE_H);
369	  return row + 1;
370	}
