  int items[8];             /* Entry, -1 About, -2 all apps */
  FAR char *save;
  FAR char *id;
  lv_obj_t *tile;
  int32_t y;
  int rows = 0;
  int n = 0;
  int i;

  for (id = strtok_r(pinned, " ", &save); id != NULL && n < 6;
       id = strtok_r(NULL, " ", &save))
    {
      items[n] = launcher_find_entry(id);
      if (items[n] >= 0)
        {
          n++;
        }

      if (n == 1)
        {
          items[n++] = -1;
        }
    }

  if (n == 0)
    {
      items[n++] = -1;
    }

  items[n++] = -2;
  snprintf(count, sizeof(count), "%d APPS", g_nentries);
  all.tag = count;

  for (i = 0; i < n; i++)
