  lv_obj_add_flag(tile, LV_OBJ_FLAG_CLICKABLE);
  lv_obj_set_style_bg_color(tile, lv_color_hex(UI_RULE), LV_STATE_PRESSED);
  lv_obj_set_style_pad_hor(tile, LAUNCHER_TILE_PAD, 0);
  lv_obj_set_pos(tile, UI_MARGIN, y);
