static int s6_uart_receive(struct uart_dev_s *dev, unsigned int *status)
{
  const struct s6_uart_priv_s *priv = dev->priv;
  uint32_t uart_status = s6_uart_getreg(priv, S6_UART_STATUS_OFFSET);

