504	/****************************************************************************
505	 * Name: CoreMark
506	 *
507	 * The coremark builtin runs as a task of its own on one core, below the
508	 * UI priority.  Its stdout goes into a pipe that a thread reads for the
509	 * "Iterations/Sec" line, so the UI keeps running (and keeps still).
510	 ****************************************************************************/
511	
512	#ifdef BENCH_COREMARK
513	static void *bench_coremark_thread(void *arg)
514	{
515	  FILE *f = fdopen((int)(intptr_t)arg, "r");
516	  int score = 0;
517	  char line[128];
518	  char *p;
519	
520	  while (fgets(line, sizeof(line), f) != NULL)
521	    {
522	      p = strstr(line, "Iterations/Sec");
523	      if (p != NULL && (p = strchr(p, ':')) != NULL)
524	        {
525	          score = atoi(p + 1);
526	        }
527	    }
528	
529	  fclose(f);
530	  g_coremark_score = score;
531	  return NULL;
532	}
533	
534	static int bench_coremark_start(void)
535	{
536	  FAR const struct builtin_s *app;
537	  pthread_t thread;
538	  cpu_set_t cpus;
539	  int index = builtin_isavail("coremark");
540	  int fd[2];
541	  int out;
542	  pid_t pid;
543	
544	  if (index < 0 || pipe(fd) < 0)
545	    {
546	      return -1;
547	    }
548	
549	  /* The task inherits stdout as it is while it is created */
550	
551	  app = builtin_for_index(index);
552	  out = dup(STDOUT_FILENO);
553	  fflush(stdout);
554	  dup2(fd[1], STDOUT_FILENO);
555	  pid = task_create(app->name, BENCH_COREMARK_PRIO, app->stacksize,
556	                    app->main, NULL);
557	  dup2(out, STDOUT_FILENO);
558	  close(out);
559	  close(fd[1]);
560	
561	  if (pid < 0)
562	    {
563	      close(fd[0]);
564	      return -1;
565	    }
566	
567	  CPU_ZERO(&cpus);
568	  CPU_SET(BENCH_COREMARK_CPU, &cpus);
569	  sched_setaffinity(pid, sizeof(cpus), &cpus);
570	
571	  g_coremark_score = -1;
572	  pthread_create(&thread, NULL, bench_coremark_thread,
573	                 (void *)(intptr_t)fd[0]);
574	  pthread_detach(thread);
575	  return 0;
576	}
577	#endif
578	
