327	
328	static void launcher_load_entries(void)
329	{
330	  struct launcher_entry_s *e;
331	  FAR char *save;
332	  FAR char *id;
333	  int i;
334	
335	  g_nentries = 0;
336	  for (id = strtok_r(g_app_list, " ", &save);
337	       id != NULL && g_nentries < LAUNCHER_MAX_APPS;
338	       id = strtok_r(NULL, " ", &save))
339	    {
340	      e = &g_entries[g_nentries];
341	
342	      for (i = 0; i < nitems(g_apps) && strcmp(g_apps[i].id, id) != 0;
343	           i++);
344	
345	      if (i < nitems(g_apps))
346	        {
347	          e->app = g_apps[i];
348	        }
349	      else
350	        {
351	          for (i = 0; i < sizeof(e->title) - 1 && id[i] != '\0'; i++)
352	            {
353	              e->title[i] = toupper(id[i]);
354	            }
355	
356	          e->title[i] = '\0';
357	          memset(&e->app, 0, sizeof(e->app));
358	          e->app.id = id;
359	          e->app.group = LAUNCHER_OPENVELA;
360	          e->app.title = e->title;
361	          e->app.desc = "";
362	          e->app.icon = LV_SYMBOL_PLAY;
363	          e->app.bg = UI_INK_2;
364	          e->app.fg = 0xffffff;
365	          e->app.icon_color = 0xffffff;
366	        }
367	
368	      e->index = builtin_isavail(e->app.prog ? e->app.prog : id);
369	      if (e->index >= 0)
370	        {
371	          g_nentries++;
372	        }
373	    }
374	}
