void snake_game_deinit(void)
{
    // Free snake body memory
    snake_node_t* current = g_game.snake_head;
    while (current != NULL) {
        snake_node_t* next = current->next;
        free(current);
        current = next;
    }

    // Delete timer
    if (g_game.game_timer) {
        lv_timer_del(g_game.game_timer);
        g_game.game_timer = NULL;
    }
