/****************************************************************************
 * app/lvdemo/lvdemo.h
 *
 * The openvela apps lvdemo hosts, see lvdemo_snake.c and
 * lvdemo_whackmole.c.
 ****************************************************************************/

#ifndef __APP_LVDEMO_LVDEMO_H
#define __APP_LVDEMO_LVDEMO_H

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

void lvdemo_snake_create(void);
void lvdemo_snake_destroy(void);
void lvdemo_whackmole_create(void);

#endif /* __APP_LVDEMO_LVDEMO_H */

/****************************************************************************
 * app/lvdemo/lvdemo_snake.c
 *
 * The snake game of packages/demos/snake_game, built here instead of as
 * its own app, whose main loop never returns.  Its source is not changed:
 *
 * - snake_game.h is included first with a grid for the portrait screen.
 *   The game is made for a 1200px wide landscape screen (60 x 35 cells of
 *   20px); 52 x 76 cells fill 1080 x 1920 instead.  The header guard keeps
 *   snake_game.c from including it again.
 * - Its state is static and outlives LVGL in the flat build, so it is
 *   cleared before each start and the snake is freed on exit.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <string.h>

#include "snake_game.h"

#undef GAME_GRID_WIDTH
#undef GAME_GRID_HEIGHT
#define GAME_GRID_WIDTH       52
#define GAME_GRID_HEIGHT      76

#include "snake_game.c"

#include "lvdemo.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void lvdemo_snake_create(void)
{
  memset(&g_game, 0, sizeof(g_game));
  last_score = 0;
  no_score_frames = 0;
  snake_game_create();
}

void lvdemo_snake_destroy(void)
{
  snake_game_deinit();
  g_game.snake_head = NULL;
}

/****************************************************************************
 * app/lvdemo/lvdemo_whackmole.c
 *
 * Whack-a-mole of packages/demos/Whackmole, built here instead of as its
 * own app, whose main loop never returns.  Its source is not changed:
 *
 * - Its timers and objects are kept in statics that outlive LVGL in the
 *   flat build; a second start would delete them again.  They are cleared
 *   before each start.
 * - It is made for a 4:3 landscape screen and sizes the holes in percent
 *   of the screen, which stretches the moles on the portrait screen.  The
 *   holes are made square, the background covers the screen instead of
 *   being stretched and the START button gets bigger.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "Whackmole.c"
#include "pic/MiSans_Normal.c"
#include "pic/grassland.c"
#include "pic/hammer_image.c"
#include "pic/mole_image.c"

#include "lvdemo.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define LVDEMO_HOLE_SIZE      180
#define LVDEMO_START_W        360
#define LVDEMO_START_H        120

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void lvdemo_whackmole_create(void)
{
  lv_obj_t *obj;
  uint32_t i;

  game_screen = NULL;
  game_screen_bg = NULL;
  hit_effect = NULL;
  hammer_cursor = NULL;
  game_timer = NULL;
  mole_timer = NULL;
  score = 0;
  game_time = GAME_TIME;

  whackmole_app_create();

  lv_image_set_inner_align(game_screen_bg, LV_IMAGE_ALIGN_COVER);

  for (i = 0; i < MOLE_COUNT; i++)
    {
      lv_obj_set_size(lv_obj_get_parent(moles[i]), LVDEMO_HOLE_SIZE,
                      LVDEMO_HOLE_SIZE);
    }

  for (i = 0; i < lv_obj_get_child_count(game_screen); i++)
    {
      obj = lv_obj_get_child(game_screen, i);
      if (lv_obj_check_type(obj, &lv_button_class))
        {
          lv_obj_set_size(obj, LVDEMO_START_W, LVDEMO_START_H);
        }
    }
}

/****************************************************************************
 * app/lvdemo/lvdemo_main.c
 *
 * Runs one LVGL demo or openvela app, chosen by the argument:
 *
 *   lvdemo benchmark [exit]   LVGL benchmark, summary on the console;
 *                             with "exit" it returns when it is done
 *   lvdemo widgets            LVGL widgets
 *   lvdemo snake              snake game of packages/demos
 *   lvdemo whackmole          whack-a-mole of packages/demos
 *
 * None of them can return by itself, lvdemo puts a back button in the
 * bottom left corner and releases LVGL on the way out like the other apps.
 * The LVGL performance overlay stays visible here.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/param.h>

#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <lvgl/lvgl.h>
#include <lvgl/demos/lv_demos.h>

#include "lvdemo.h"
#include "lvx_ui.h"

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct lvdemo_s
{
  const char *name;
  void (*create)(void);
  void (*destroy)(void);    /* May be NULL */
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

#ifdef CONFIG_LV_USE_DEMO_BENCHMARK
static void lvdemo_benchmark(void);
#endif

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct lvdemo_s g_demos[] =
{
#ifdef CONFIG_LV_USE_DEMO_BENCHMARK
  { "benchmark", lvdemo_benchmark, NULL },
#endif
#ifdef CONFIG_LV_USE_DEMO_WIDGETS
  { "widgets", lv_demo_widgets, NULL },
#endif
  { "snake", lvdemo_snake_create, lvdemo_snake_destroy },
  { "whackmole", lvdemo_whackmole_create, NULL },
};

static bool g_running;
static bool g_exit_when_done;       /* "benchmark exit" */

/****************************************************************************
 * Private Functions
 ****************************************************************************/

#ifdef CONFIG_LV_USE_DEMO_BENCHMARK
static void lvdemo_benchmark(void)
{
  static int runs;

  /* The demo sums up its results in a static table that it never clears,
   * a second run in the same boot reports the average of all runs
   */

  if (runs++ > 0)
    {
      printf("lvdemo: benchmark run %d since boot, the summary averages "
             "all of them\n", runs);
    }

  lv_demo_benchmark();
}
#endif

/* LVGL log goes to the console.  The benchmark writes its summary with
 * LV_LOG, the last line tells that it is done.
 */

#ifdef CONFIG_LV_USE_LOG
static void lvdemo_log_cb(lv_log_level_t level, const char *buf)
{
  UNUSED(level);

  fputs(buf, stdout);
  if (g_exit_when_done && strstr(buf, "All scenes avg.") != NULL)
    {
      g_running = false;
    }
}
#endif

static void lvdemo_back_cb(lv_event_t *e)
{
  UNUSED(e);
  g_running = false;
}

static void lvdemo_usage(void)
{
  int i;

  fprintf(stderr, "usage: lvdemo <demo>, one of:");
  for (i = 0; i < nitems(g_demos); i++)
    {
      fprintf(stderr, " %s", g_demos[i].name);
    }

  fprintf(stderr, "\n");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  const struct lvdemo_s *demo = NULL;
  lv_nuttx_result_t result;
  lv_nuttx_dsc_t info;
  lv_obj_t *back;
  uint32_t idle;
  int i;

  for (i = 0; argc > 1 && i < nitems(g_demos); i++)
    {
      if (strcmp(argv[1], g_demos[i].name) == 0)
        {
          demo = &g_demos[i];
        }
    }

  if (demo == NULL)
    {
      lvdemo_usage();
      return 1;
    }

  /* LVGL is one global instance, shared by every task of the flat build */

  if (lv_is_initialized())
    {
      fprintf(stderr, "lvdemo: LVGL is busy, start it from the launcher\n");
      return 1;
    }

  lv_init();

  lv_nuttx_dsc_init(&info);
  lv_nuttx_init(&info, &result);

  if (result.disp == NULL || result.indev == NULL)
    {
      fprintf(stderr, "lvdemo: no display or touchscreen\n");
      lv_nuttx_deinit(&result);
      lv_deinit();
      return 1;
    }

#ifdef CONFIG_LV_USE_LOG
  lv_log_register_print_cb(lvdemo_log_cb);
#endif

  g_exit_when_done = argc > 2 && strcmp(argv[2], "exit") == 0;
  demo->create();

  back = ui_back(lv_layer_top(), UI_INK, lvdemo_back_cb);
  lv_obj_set_style_bg_opa(back, LV_OPA_80, 0);
  lv_obj_align(back, LV_ALIGN_BOTTOM_LEFT, UI_GAP, -UI_GAP);

  g_running = true;
  while (g_running)
    {
      idle = lv_timer_handler();
      usleep(MAX(idle, 1) * 1000);
    }

  if (demo->destroy != NULL)
    {
      demo->destroy();
    }

  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
}

